// Transcribed from solid-js@2.0.0-rc.9, whose `types/index.d.ts:1` re-exports
// every name here from `@solidjs/signals@2.0.0-rc.9`.
//
// Byte-faithful, because every claim in `expected.json` rests on them:
//
// - `untrack`                 `dist/types/core/core.d.ts:105`
// - both `omit` overloads     `dist/types/store/utils.d.ts:250-251`, and the
//   `Omit` they return        `:216-218` (the predicate overload is new in rc.9)
// - `until`, `UntilOptions`,  `dist/types/signals.d.ts:608`, `:537-544`, `:536`
//   `Truthy`                  (all new in rc.9)
//
// Doc comments are dropped; nothing else is reduced.

export type Omit<T, K extends readonly (keyof T)[]> = {
    [P in keyof T as Exclude<P, K[number]>]: T[P];
};
export type Truthy<T> = Exclude<T, false | 0 | 0n | "" | null | undefined>;
export interface UntilOptions {
    timeout?: number;
    signal?: AbortSignal;
}

export declare function untrack<T>(fn: () => T, strictReadLabel?: string | false): T;
export declare function omit<T extends Record<any, any>, K extends readonly (keyof T)[]>(props: T, ...keys: K): Omit<T, K>;
export declare function omit<T extends Record<any, any>>(props: T, hidden: (key: keyof T & (string | symbol)) => boolean): Partial<T>;
export declare function until<T>(fn: () => T, options?: UntilOptions): Promise<Truthy<T>>;

// `@solidjs/web`'s `ValidComponent` names this; `types/client/component.d.ts:6`.
// Its return type is solid-js' `Element` union, reduced to `unknown` here:
// nothing in this fixture renders.
export type Component<P extends Record<string, any> = {}> = (props: P) => unknown;
